using System.Text.Json;
using System.Text.Json.Serialization;

namespace MultiSeat.Router;

/// <summary>
/// Runtime configuration, normally generated by scripts/host/Start-MultiSeat.ps1 into runtime/router.json.
/// </summary>
internal sealed class RouterConfig
{
    public List<SeatEndpoint> Seats { get; set; } = new();

    /// <summary>Where keyboard/mouse pairing is remembered between runs. Defaults to pairing.json next to the config.</summary>
    public string? PairingFile { get; set; }

    public static readonly JsonSerializerOptions JsonOptions = new()
    {
        PropertyNameCaseInsensitive = true,
        ReadCommentHandling = JsonCommentHandling.Skip,
        AllowTrailingCommas = true,
        WriteIndented = true,
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
    };

    public static RouterConfig Load(string path)
    {
        var config = JsonSerializer.Deserialize<RouterConfig>(File.ReadAllText(path), JsonOptions)
            ?? throw new InvalidDataException($"{path} is empty.");

        if (config.Seats.Count == 0)
        {
            throw new InvalidDataException($"{path} does not define any seats.");
        }

        var names = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var seat in config.Seats)
        {
            if (string.IsNullOrWhiteSpace(seat.Name) || !names.Add(seat.Name))
            {
                throw new InvalidDataException($"Seat names must be unique and non-empty ('{seat.Name}').");
            }

            if (string.IsNullOrWhiteSpace(seat.Address) || seat.Port is <= 0 or > 65535)
            {
                throw new InvalidDataException($"Seat '{seat.Name}' needs a valid address and port.");
            }

            if (string.IsNullOrWhiteSpace(seat.Secret))
            {
                throw new InvalidDataException($"Seat '{seat.Name}' has no secret.");
            }
        }

        config.PairingFile ??= Path.Combine(Path.GetDirectoryName(Path.GetFullPath(path)) ?? ".", "pairing.json");
        return config;
    }
}

internal sealed class SeatEndpoint
{
    public string Name { get; set; } = "";

    public string Address { get; set; } = "";

    public int Port { get; set; } = 47800;

    public string Secret { get; set; } = "";
}

/// <summary>Which physical keyboard and mouse belong to a seat.</summary>
internal sealed class SeatPairing
{
    public string Seat { get; set; } = "";

    public int Keyboard { get; set; }

    public string? KeyboardHardwareId { get; set; }

    public int Mouse { get; set; }

    public string? MouseHardwareId { get; set; }
}
